INSERT INTO `mdl_hvp_libraries` VALUES (1,'FontAwesome','Font Awesome',4,5,4,0,0,'','','h5p-font-awesome.min.css','','',0,NULL,0,NULL,NULL),(2,'H5P.AdvancedText','Text',1,1,14,0,0,'','text.js','text.css','','[\n  {\n    \"name\": \"text\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"label\": \"Text\",\n    \"importance\": \"high\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"del\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"font\": {\n      \"size\": true,\n      \"color\": true,\n      \"background\": true\n    }\n  }\n]\n',0,NULL,0,NULL,'{\"disable\":false,\"disableExtraTitleField\":true}'),(3,'H5P.Audio','Audio',1,5,29,1,0,'iframe','scripts/audio.js','styles/audio.css','','[\n  {\n    \"name\": \"files\",\n    \"type\": \"audio\",\n    \"importance\": \"high\",\n    \"label\": \"Source files\",\n    \"disableCopyright\": true\n  },\n  {\n    \"name\": \"playerMode\",\n    \"type\": \"select\",\n    \"importance\": \"low\",\n    \"label\": \"Player mode\",\n    \"description\": \"Select the layout of the player.\",\n    \"options\": [\n      {\n        \"value\": \"minimalistic\",\n        \"label\": \"Minimalistic\"\n      },\n      {\n        \"value\": \"full\",\n        \"label\": \"Full\"\n      },\n      {\n        \"value\": \"transparent\",\n        \"label\": \"Transparent\"\n      }\n    ],\n    \"default\": \"minimalistic\"\n  },\n  {\n    \"name\": \"fitToWrapper\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"label\": \"Fit to wrapper\",\n    \"default\": false,\n    \"descriptions\": \"Adjust audioplayer size to use available space\",\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"playerMode\",\n          \"equals\": \"minimalistic\"\n        },\n        {\n          \"field\": \"playerMode\",\n          \"equals\": \"full\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"controls\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"label\": \"Enable controls\",\n    \"default\": true,\n    \"description\": \"Controls allow the user to for instance pause the audio\",\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"playerMode\",\n          \"equals\": \"full\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"autoplay\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"label\": \"Enable autoplay\",\n    \"description\": \"With autoplay the audio starts to play immediately. Do note that this is not supported by all browsers\"\n  },\n  {\n    \"name\": \"playAudio\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Play audio (Readspeaker)\",\n    \"common\": true,\n    \"default\": \"Play audio\"\n  },\n  {\n    \"name\": \"pauseAudio\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Pause audio (Readspeaker)\",\n    \"common\": true,\n    \"default\": \"Pause audio\"\n  },\n  {\n    \"name\": \"contentName\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Audio content name\",\n    \"common\": true,\n    \"default\": \"Audio\"\n  },\n  {\n    \"name\": \"audioNotSupported\",\n    \"type\": \"text\",\n    \"label\": \"Audio not supported message\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Your browser does not support this audio\"\n  }\n]\n',0,NULL,1,NULL,NULL),(4,'H5P.Blanks','Fill in the Blanks',1,14,37,1,0,'iframe','js/blanks.js, js/cloze.js','css/blanks.css','','[\n  {\n    \"name\": \"media\",\n    \"type\": \"group\",\n    \"label\": \"Media\",\n    \"importance\": \"medium\",\n    \"fields\": [\n      {\n        \"name\": \"type\",\n        \"type\": \"library\",\n        \"label\": \"Type\",\n        \"options\": [\n          \"H5P.Image 1.1\",\n          \"H5P.Video 1.6\",\n          \"H5P.Audio 1.5\"\n        ],\n        \"optional\": true,\n        \"description\": \"Optional media to display above the question.\"\n      },\n      {\n        \"name\": \"disableImageZooming\",\n        \"type\": \"boolean\",\n        \"label\": \"Disable image zooming\",\n        \"importance\": \"low\",\n        \"default\": false,\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"type\",\n              \"equals\": \"H5P.Image 1.1\"\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"label\": \"Task description\",\n    \"importance\": \"high\",\n    \"name\": \"text\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"default\": \"Fill in the missing words\",\n    \"description\": \"A guide telling the user how to answer this task.\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  },\n  {\n    \"name\": \"questions\",\n    \"type\": \"list\",\n    \"label\": \"Text blocks\",\n    \"importance\": \"high\",\n    \"entity\": \"text block\",\n    \"min\": 1,\n    \"max\": 31,\n    \"field\": {\n      \"name\": \"question\",\n      \"type\": \"text\",\n      \"widget\": \"html\",\n      \"label\": \"Line of text\",\n      \"importance\": \"high\",\n      \"placeholder\": \"Oslo is the capital of *Norway*.\",\n      \"description\": \"\",\n      \"important\": {\n        \"description\": \"<ul><li>Blanks are added with an asterisk (*) in front and behind the correct word/phrase.</li><li>Alternative answers are separated with a forward slash (/).</li><li>You may add a textual tip, using a colon (:) in front of the tip.</li></ul>\",\n        \"example\": \"H5P content may be edited using a *browser/web-browser:Something you use every day*.\"\n      